from sqlalchemy import Column, Index, Integer, String, DateTime, ForeignKey, Enum, JSON
from sqlalchemy.dialects import mysql
from sqlalchemy.orm import declarative_base
from sqlalchemy.sql import func
from .users import Base
class BrokerPostcodeAccessCurrent(Base): __tablename__ = "broker_postcode_access_current"; broker_user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), primary_key=True, nullable=False); postcode_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("postcodes.id", ondelete="RESTRICT", onupdate="RESTRICT"), primary_key=True, nullable=False); granted_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False); granted_by = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); expires_at = Column(DateTime, nullable=True); __table_args__ = (Index("idx_broker_current_broker_user", "broker_user_id"), Index("idx_broker_current_postcode", "postcode_id"))
class BrokerPostcodeAccessHistory(Base): __tablename__ = "broker_postcode_access_history"; id = Column(mysql.BIGINT(unsigned=True), primary_key=True, autoincrement=True); broker_user_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); postcode_id = Column(mysql.BIGINT(unsigned=True), ForeignKey("postcodes.id", ondelete="RESTRICT", onupdate="RESTRICT"), nullable=False); granted_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False); granted_by = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="CASCADE", onupdate="CASCADE"), nullable=False); revoked_at = Column(DateTime, nullable=True); revoked_by = Column(mysql.BIGINT(unsigned=True), ForeignKey("users.id", ondelete="SET NULL", onupdate="SET NULL"), nullable=True); status = Column(Enum("ACTIVE","REVOKED","EXPIRED"), nullable=False); reason = Column(String(500), nullable=True); metadata_json = Column("metadata", JSON, nullable=True); created_at = Column(DateTime, server_default=func.current_timestamp(), nullable=False); __table_args__ = (Index("idx_broker_history_broker_user", "broker_user_id"), Index("idx_broker_history_postcode", "postcode_id"), Index("idx_broker_history_status", "status"))
